// agent-ledger plugin for OpenCode (V1 plugin API, opencode 1.x). agent-ledger-plugin:v1
// Generated by `agent-ledger init --agent opencode`. Do not edit: re-run init instead.
//
// Every tool call is sent to agent-ledger before it runs. A "deny" throws, which makes OpenCode
// skip the tool and hand the reason back to the model. OpenCode V1 plugins cannot open a
// permission prompt, so an "ask" also blocks (with a "needs human approval" message): in a
// headless `opencode run` an ask would be auto-rejected anyway. Results, failures, prompts and
// session start/stop are recorded too. This file must export exactly one function.
import { spawn } from "node:child_process"

const HOOK = __HOOK_ARGV__
const FAIL_CLOSED = __FAIL_CLOSED__
const TIMEOUT_MS = 10000

function call(payload) {
  return new Promise((resolve) => {
    let child
    try {
      child = spawn(HOOK[0], HOOK.slice(1), { stdio: ["pipe", "pipe", "pipe"] })
    } catch (e) {
      resolve({ failed: `cannot start agent-ledger: ${e.message}` })
      return
    }
    let out = ""
    let err = ""
    let done = false
    const finish = (value) => {
      if (!done) {
        done = true
        clearTimeout(timer)
        resolve(value)
      }
    }
    const timer = setTimeout(() => {
      child.kill("SIGKILL")
      finish({ failed: "agent-ledger timed out" })
    }, TIMEOUT_MS)
    child.stdout.on("data", (d) => (out += d))
    child.stderr.on("data", (d) => (err += d))
    child.on("error", (e) => finish({ failed: `cannot start agent-ledger: ${e.message}` }))
    child.on("close", (code) => {
      if (code === 2) return finish({ failed: err.trim() || "agent-ledger failed (fail-closed)", closed: true })
      if (!out.trim()) return finish({})
      try {
        finish(JSON.parse(out))
      } catch {
        finish({ failed: "agent-ledger returned invalid output" })
      }
    })
    child.stdin.on("error", () => {})
    child.stdin.end(JSON.stringify(payload))
  })
}

export const AgentLedger = async ({ directory, worktree }) => {
  const base = { agent: "opencode", directory, worktree }
  const failed = new Set()
  const record = async (payload) => {
    try {
      await call({ ...base, ...payload })
    } catch {
      // recording must never break the session
    }
  }
  return {
    "tool.execute.before": async (input, output) => {
      const res = await call({ ...base, phase: "tool.before", tool: input.tool, sessionID: input.sessionID,
                               callID: input.callID, args: output.args })
      if (res.failed) {
        if (FAIL_CLOSED || res.closed) throw new Error(`agent-ledger: ${res.failed}`)
        return
      }
      if (res.decision === "deny") throw new Error(res.reason || "agent-ledger: blocked by policy")
      if (res.decision === "ask") {
        throw new Error(`${res.reason || "agent-ledger"} - this needs human approval, so it was not run. ` +
                        "Ask the user to run it or to change the policy.")
      }
    },
    "tool.execute.after": async (input, output) => {
      await record({ phase: "tool.after", tool: input.tool, sessionID: input.sessionID, callID: input.callID,
                     args: input.args, output: { title: output?.title, output: output?.output, metadata: output?.metadata } })
    },
    "chat.message": async (input, output) => {
      const text = (output?.parts || []).filter((p) => p && p.type === "text").map((p) => p.text).join("\n")
      await record({ phase: "chat.message", sessionID: input.sessionID, prompt: text })
    },
    event: async ({ event }) => {
      const p = event?.properties || {}
      if (["session.created", "session.idle", "session.deleted", "session.error"].includes(event?.type)) {
        await record({ phase: "event", event_type: event.type, sessionID: p.sessionID || p.info?.id,
                       error: p.error ? String(p.error?.message || p.error?.name || p.error) : undefined })
      } else if (event?.type === "message.part.updated") {
        // tool.execute.after does not fire for failed tools, so failures come from part updates
        const part = p.part
        if (part?.type === "tool" && part.state?.status === "error" && !failed.has(part.callID)) {
          failed.add(part.callID)
          await record({ phase: "tool.error", tool: part.tool, sessionID: part.sessionID || p.sessionID,
                         callID: part.callID, args: part.state.input, error: part.state.error })
        }
      }
    },
  }
}
